<?php
require 'config/database.php';$pageTitle='Transportadores';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$data=[trim($_POST['name']),trim($_POST['document']),trim($_POST['phone']),trim($_POST['vehicle'])];if($id){$data[]=$id;$pdo->prepare("UPDATE transporters SET name=?,document=?,phone=?,vehicle=? WHERE id=?")->execute($data);}else{$pdo->prepare("INSERT INTO transporters(name,document,phone,vehicle) VALUES(?,?,?,?)")->execute($data);}header('Location: transporters.php');exit;}
if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM transporters WHERE id=?")->execute([(int)$_GET['delete']]);header('Location: transporters.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM transporters WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$items=$pdo->query("SELECT * FROM transporters ORDER BY id DESC")->fetchAll();require 'includes/header.php';?>
<h1 class="page-title">Transportadores</h1><p class="muted mb-4">Gerencie motoristas e empresas responsáveis pelo transporte.</p>
<div class="row g-4"><div class="col-lg-4"><div class="card content-card"><h5><?= $edit?'Editar':'Novo' ?> transportador</h5><form method="post"><input type="hidden" name="id" value="<?= $edit['id']??'' ?>"><label class="form-label mt-2">Nome</label><input class="form-control mb-3" name="name" required value="<?= htmlspecialchars($edit['name']??'') ?>"><label class="form-label">CPF/CNPJ</label><input class="form-control mb-3" name="document" value="<?= htmlspecialchars($edit['document']??'') ?>"><label class="form-label">Telefone</label><input class="form-control mb-3" name="phone" value="<?= htmlspecialchars($edit['phone']??'') ?>"><label class="form-label">Veículo</label><input class="form-control mb-3" name="vehicle" placeholder="Ex.: Caminhão baú" value="<?= htmlspecialchars($edit['vehicle']??'') ?>"><button class="btn btn-primary w-100">Salvar transportador</button></form></div></div>
<div class="col-lg-8"><div class="card content-card"><h5 class="mb-3">Transportadores cadastrados</h5><div class="table-responsive"><table class="table"><thead><tr><th>Nome</th><th>Documento</th><th>Telefone</th><th>Veículo</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $t): ?><tr><td><?= htmlspecialchars($t['name']) ?></td><td><?= htmlspecialchars($t['document']) ?></td><td><?= htmlspecialchars($t['phone']) ?></td><td><?= htmlspecialchars($t['vehicle']) ?></td><td><a href="?edit=<?= $t['id'] ?>">Editar</a> · <a class="text-danger" onclick="return confirm('Excluir?')" href="?delete=<?= $t['id'] ?>">Excluir</a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="5" class="muted">Nenhum transportador cadastrado.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
<?php require 'includes/footer.php'; ?>
